<?php
declare(strict_types=1);namespace MiniErp\Platform;use MiniErp\Repositories\PlatformAdminRepository;use PDO;final class MultiTenantRuntimeFactory{public static function create(PDO $main,string $root):array{$cfg=require $root.'/config.php';$d=$cfg['db'];$server=new PDO(sprintf('mysql:host=%s;port=%s;charset=utf8mb4',$d['host'],$d['port']),$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$catalog=new MigrationCatalog($root.'/migrations');$operations=new MultiTenantOperationRepository($main);$precheck=new MultiTenantMigrationPrecheck($server,$main);$executor=new MultiTenantMigrationExecutor($server,$d,dirname($root).'/backups/MULTITENANT',$operations);$service=new MultiTenantMigrationService($main,$catalog,$precheck,$operations,new PlatformAdminRepository($main),$executor);return[$service,$catalog,$operations];}}
